def count_primes(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    p = 2
    while (p * p <= limit):
        if (is_prime[p]):
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1
    count = 0
    for i in range(2, limit + 1):
        if is_prime[i]:
            count += 1
    return count

# Check up to 40 to confirm where pi(n) crosses 11
print(f"pi(30): {count_primes(30)}")
print(f"pi(31): {count_primes(31)}")
print(f"pi(36): {count_primes(36)}")
print(f"pi(37): {count_primes(37)}")

